import Foundation

/// Spots throwaway ("10-minute") email addresses so the app can explain, before sending a code,
/// that TakaDe needs a permanent address. This is a courtesy check only: the server enforces the
/// same list in a Supabase "Before User Created" hook, which also covers Apple and Google sign-in.
///
/// The list is `Resources/disposable-email-domains.txt`, generated by
/// `scripts/update-disposable-domains.py` from the community-maintained disposable-email-domains
/// project. The same script writes the server's copy, so both stay in step.
public struct DisposableEmail: Sendable {
    /// Apple's Hide My Email relay is a real, permanent inbox, never treated as throwaway.
    static let alwaysAllowed: Set<String> = ["privaterelay.appleid.com"]

    private let domains: Set<String>

    public init(domains: some Sequence<String>) {
        self.domains = Set(domains.map { $0.lowercased() })
    }

    /// The bundled list, loaded once on first use.
    public static let bundled = DisposableEmail(domains: loadBundledList())

    /// True when the address's domain, or any parent domain, is a known throwaway provider.
    /// "x@sub.mailinator.com" matches "mailinator.com". A bare top-level domain never matches.
    public func isDisposable(_ email: String) -> Bool {
        guard let domain = Self.domain(of: email), !Self.alwaysAllowed.contains(domain) else { return false }
        var labels = domain.split(separator: ".")
        while labels.count >= 2 {
            if domains.contains(labels.joined(separator: ".")) { return true }
            labels.removeFirst()
        }
        return false
    }

    static func domain(of email: String) -> String? {
        let trimmed = email.trimmingCharacters(in: .whitespacesAndNewlines)
        guard let at = trimmed.lastIndex(of: "@") else { return nil }
        var domain = trimmed[trimmed.index(after: at)...].lowercased()
        while domain.hasSuffix(".") { domain.removeLast() }
        return domain.isEmpty ? nil : domain
    }

    static func parse(_ text: String) -> [String] {
        text.split(whereSeparator: \.isNewline)
            .map { $0.trimmingCharacters(in: .whitespaces) }
            .filter { !$0.isEmpty && !$0.hasPrefix("#") }
    }

    private static func loadBundledList() -> [String] {
        guard let url = Bundle.module.url(forResource: "disposable-email-domains", withExtension: "txt"),
              let text = try? String(contentsOf: url, encoding: .utf8) else {
            assertionFailure("disposable-email-domains.txt is missing from TakaDeCore")
            return []
        }
        return parse(text)
    }
}
